insert into campsites (id, park_id, name, lat, lng, permit_required, site_type, description) values
  ('00000000-0000-4000-8000-000000003206', '00000000-0000-4000-8000-000000000005', 'Junction Meadow Backpacker Camp', 36.754274, -118.442985, true, 'designated', 'Designated camping along Bubbs Creek at the confluence with East Creek, about 10 miles from Road''s End -- the first night''s stop on the way to Charlotte Lake, and the third night''s stop on the way back out.'),
  ('00000000-0000-4000-8000-000000003207', '00000000-0000-4000-8000-000000000005', 'Charlotte Lake Backpacker Camp', 36.7760325, -118.4267787, true, 'designated', 'Designated camping at 10,544 ft near Charlotte Lake, just off the John Muir/Pacific Crest Trail below the Kearsarge Pass/Bullfrog Lake junction. Bear boxes provided; a popular staging spot for Kearsarge Pass exits.'),
  ('00000000-0000-4000-8000-000000003208', '00000000-0000-4000-8000-000000000005', 'Frypan Meadow Backpacker Camp', 36.8534645, -118.698618, true, 'designated', 'The first -- and effectively only -- legal campsite on the steep Lewis Creek Trail out of Cedar Grove, at about 7,800 ft. Capped at 25 people per day given its small size.');
