insert into parking_locations (id, park_id, trail_id, trailhead_name, lat, lng, address, permit_notes) values
  ('00000000-0000-4000-8000-000000003404', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003004', 'Zumwalt Meadow Trailhead', 36.791097, -118.598381, 'Kings Canyon Scenic Byway (CA-180), Kings Canyon National Park, CA 93633', 'Small roadside pullout with a footbridge over the South Fork Kings River; fills quickly on summer weekends.'),
  ('00000000-0000-4000-8000-000000003405', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003005', 'Roaring River Falls Trailhead', 36.783803, -118.622164, 'Kings Canyon Scenic Byway (CA-180), Kings Canyon National Park, CA 93633', 'Paved roadside pullout; short wheelchair-accessible walk to the falls overlook.'),
  ('00000000-0000-4000-8000-000000003406', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003006', 'Hotel Creek Trailhead', 36.793579, -118.666488, 'Kings Canyon Scenic Byway (CA-180), near Sentinel Campground, Kings Canyon National Park, CA 93633', 'Roadside parking near Sentinel Campground; the steep climb to the overlook starts immediately.'),
  ('00000000-0000-4000-8000-000000003407', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003007', 'Road''s End Permit Station', 36.794682, -118.5826819, 'CA-180, Kings Canyon National Park, CA 93633 (end of Kings Canyon Scenic Byway, Cedar Grove)', 'At the end of CA-180 past Cedar Grove; overnight parking available.'),
  ('00000000-0000-4000-8000-000000003408', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003008', 'Don Cecil Trailhead', 36.788693, -118.67045, 'Kings Canyon Scenic Byway (CA-180), Cedar Grove, Kings Canyon National Park, CA 93633', 'Small layby on the north side of CA-180, just east of the Sentinel Campground turnoff.'),
  ('00000000-0000-4000-8000-000000003409', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003009', 'Grant Grove Parking Area', 36.747404, -118.971315, 'General Grant Tree Trail, Grant Grove, Kings Canyon National Park, CA 93633', 'Large paved lot at the General Grant Tree Trailhead in Grant Grove.'),
  ('00000000-0000-4000-8000-000000003410', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003010', 'Road''s End Permit Station', 36.794682, -118.5826819, 'CA-180, Kings Canyon National Park, CA 93633 (end of Kings Canyon Scenic Byway, Cedar Grove)', 'Same trailhead as the Rae Lakes Loop and Paradise Valley. Overnight parking available; permits and bear canister loans at the permit station.'),
  ('00000000-0000-4000-8000-000000003411', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003011', 'Lewis Creek Trailhead', 36.800201, -118.691237, 'Kings Canyon Scenic Byway (CA-180), near Sheep Creek Campground, Kings Canyon National Park, CA 93633', 'Roadside trailhead about 1.25 miles past the Cedar Grove Overlook turnoff.');
insert into permits (id, park_id, trail_id, name, description, cost_usd, application_url, application_window, max_group_size, office_name, office_address, office_lat, office_lng) values
  ('00000000-0000-4000-8000-000000003504', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003010', 'Sequoia & Kings Canyon Wilderness Permit', 'Required for all overnight backcountry travel; Sequoia and Kings Canyon share one wilderness permit system. $15 per trip plus $5 per person during quota season. Shares the Road''s End trailhead quota with the Rae Lakes Loop and Paradise Valley.', 15.00, 'https://www.recreation.gov/permits/445857', 'Quota season ~May 22-Sept 26. Reservations up to 6 months ahead, released daily at 7am PT.', 15, 'Road''s End Wilderness Permit Station', 'CA-180, Kings Canyon National Park, CA 93633 (end of Kings Canyon Scenic Byway, Cedar Grove)', 36.794682, -118.5826819),
  ('00000000-0000-4000-8000-000000003505', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003011', 'Sequoia & Kings Canyon Wilderness Permit', 'Required for all overnight backcountry travel; Sequoia and Kings Canyon share one wilderness permit system. $15 per trip plus $5 per person during quota season. Frypan Meadow is capped at 25 people per day, so this entry point has a small daily quota.', 15.00, 'https://www.recreation.gov/permits/445857', 'Quota season ~May 22-Sept 26. Reservations up to 6 months ahead, released daily at 7am PT.', 15, 'Road''s End Wilderness Permit Station', 'CA-180, Kings Canyon National Park, CA 93633 (end of Kings Canyon Scenic Byway, Cedar Grove)', 36.794682, -118.5826819);
insert into sights (id, park_id, trail_segment_id, name, description, mile_marker, lat, lng) values
  ('00000000-0000-4000-8000-000000003113', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003051', 'Roaring River Falls', 'A powerful waterfall rushing through a narrow granite chute, viewed from a short paved, wheelchair-accessible path.', 0.13, 36.782263, -118.621595),
  ('00000000-0000-4000-8000-000000003114', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003061', 'Cedar Grove Overlook', 'A rocky overlook atop the Hotel Creek Trail''s switchbacks, with sweeping views of Cedar Grove village and the Sierra crest.', 1.67, 36.801649, -118.67218),
  ('00000000-0000-4000-8000-000000003115', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003071', 'Mist Falls', 'One of the largest waterfalls in the parks, reached via a rocky, moderately steep final pitch above the South Fork Kings River.', 4.61, 36.821396, -118.547775),
  ('00000000-0000-4000-8000-000000003116', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003081', 'Lookout Peak', 'An 8,531 ft summit with the site of an old fire lookout, reached via a rough use-trail scramble off the Don Cecil Trail. Views of Kings Canyon, the Monarch Divide, and Sentinel Ridge.', 5.31, 36.773188, -118.716053),
  ('00000000-0000-4000-8000-000000003117', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003102', 'Charlotte Lake', 'A 10,544 ft subalpine lake just off the John Muir/Pacific Crest Trail, a popular staging spot for Kearsarge Pass exits.', 5.04, 36.7760325, -118.4267787),
  ('00000000-0000-4000-8000-000000003118', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003111', 'Frypan Meadow', 'A subalpine meadow at 7,841 ft, the destination of the steep Lewis Creek Trail climb out of Cedar Grove.', 6.0, 36.8534645, -118.698618),
  ('00000000-0000-4000-8000-000000003119', '00000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000003091', 'General Grant Tree', 'The world''s second-largest tree by volume and the nation''s only living National Shrine, 268 ft tall. The loop trail also passes the Lincoln Tree, the walk-through Fallen Monarch, and the 1872 Gamlin Cabin.', 0.4, 36.7484, -118.9718);
